/// <summary>
/// Gets and sets packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[DataMemberAttribute, 
 AifQueryTypeAttribute('_packedQuery',
 querystr(METItemFilterQuery))]
public str parmQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// get query method
/// </summary>
/// <returns>get query</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// set query method
/// </summary>
/// <param name = "_query">query to encode</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
